import React from 'react';

const TableViewComponent = ({ results }) => {
  if (!results || !results.length) {
    return <div>No results found.</div>;
  }

  return (
    <table className="results-table table-auto w-full border-collapse border border-gray-300 dark:border-gray-700">
      <thead className="bg-gray-100 dark:bg-gray-800">
        <tr>
          <th className="border p-2">Image</th>
          <th className="border p-2">Title</th>
          <th className="border p-2">Categories</th>
          <th className="border p-2">Year</th>
        </tr>
      </thead>
      <tbody>
        {results.map((result, index) => (
          <tr key={index} className="border-t hover:bg-gray-50 dark:hover:bg-gray-900">
            {/* Column 1: Image */}
            <td className="border p-2 text-center">
              {result.page_image_ext ? (
                <a href={result.full_title} title={result.title}>
                  <img
                    src={result.page_image_ext}
                    alt={result.title}
                    className="w-20 h-20 object-cover rounded border dark:border-gray-600"
                  />
                </a>
              ) : (
                <div className="w-20 h-20 bg-gray-200 dark:bg-gray-700 rounded mx-auto" />
              )}
            </td>

            {/* Column 2: Title */}
            <td className="border p-2 align-top text-sm text-blue-600 dark:text-blue-300">
              <a href={result.full_title} className="hover:underline font-semibold">
                {result.title}
              </a>
            </td>

            {/* Column 3: Categories as tags */}
            <td className="border p-2 align-top text-sm text-gray-700 dark:text-gray-300">
              <div className="flex flex-wrap gap-2">
                {Array.isArray(result.category) && result.category.length > 0 ? (
                  result.category.map((cat, i) => (
                    <a
                      key={i}
                      href={`/${cat.link}`}
                      className="px-2 py-0.5 bg-blue-100 text-blue-700 rounded text-xs hover:underline dark:bg-blue-800 dark:text-blue-200"
                      title={`Category: ${cat.name}`}
                    >
                      {cat.name}
                    </a>
                  ))
                ) : (
                  <span className="text-gray-400 italic">No categories</span>
                )}
              </div>
            </td>

            {/* Column 4: Year */}
            <td className="border p-2 align-top text-sm text-gray-500 dark:text-gray-400">
              {result.year || <span className="text-gray-400 italic">N/A</span>}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default TableViewComponent;
